  ["You and Allies near your Banner Regenerate 0.1% of Life per second for each Valour consumed for that Banner"] = "Вы и союзники рядом с вашим знаменем регенерируете 0.1% здоровья в секунду за каждый заряд доблести, затраченный на размещение этого знамени",
