  ["You and nearby Allies deal 30% increased Damage"] = "Вы и ближайшие союзники наносите увеличенный на 30% урон",
  ["You and nearby Allies deal 6 to 12 added Physical Damage for\\neach Impale on Enemy"] = "Вы и ближайшие союзники наносите от 6 до 12 добавленного физического урона за каждый Прокол на враге",
  ["You and nearby Allies have +30% to Elemental Resistances"] = "Вы и ближайшие союзники имеете +30% к сопротивлению стихиям",
  ["You and nearby Allies have Tailwind"] = "На вас и ближайших союзников действует Попутный ветер",
  ["You and your Totems Regenerate 1% of Life per second for each Summoned Totem"] = "Вы и ваши тотемы регенерируете 1% здоровья в секунду за каждый установленный тотем",
  ["You are Unaffected by Bleeding while Leeching"] = "Вы невосприимчивы к кровотечению во время похищения",
  ["You can Cast 2 additional Brands"] = "Вы можете сотворить 2 дополнительных клейм(-а)",
  ["You can apply an additional Curse"] = "Вы можете наложить дополнительное проклятие",
  ["You can apply up to 50 Shocks to each Enemy"] = "Вы можете наложить до 50 зарядов шока на каждого врага",
  ["You can have an additional Tincture active"] = "Вы можете активировать дополнительную микстуру",
  ["You can hire a Mercenary permanently"] = "Вы можете нанять наёмника навсегда",
  ["You can inflict +1 Hallowing Flame on Enemies"] = "Вы можете наложить +1 заряд Освящающего пламени на врагов",
  ["You can inflict Bleeding on an Enemy up to 8 times\\nYour Bleeding does not deal extra Damage while the Enemy is moving and cannot be Aggravated\\n50% less Damage with Bleeding"] = "Вы можете наложить кровотечение на врага вплоть до 8 раз\nНаложенное вами кровотечение не наносит дополнительный урон, пока враг передвигается\nНа 50% меньше урона от кровотечения",
